6. [TestClass]
7. public sealed class StringFormatterTests
8. {
9.     private readonly StringFormatter _formatter = new();
10. 
11.     // --- FormatPhoneNumber ---
12. 
13.     [TestMethod]
14.     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParentheses()
15.     {
16.         var result = _formatter.FormatPhoneNumber("5551234567");
17. 
18.         Assert.StartsWith("(555)", result);
19.     }
20. 
21.     [TestMethod]
22.     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
23.     {
24.         var result = _formatter.FormatPhoneNumber("5551234567");
25. 
