27.     }
28. 
29.     [TestMethod]
30.     public void FormatPhoneNumber_ValidDigits_MatchesExpectedPattern()
31.     {
32.         var result = _formatter.FormatPhoneNumber("5551234567");
33. 
34.         Assert.MatchesRegex(@"\(\d{3}\) \d{3}-\d{4}", result);
35.     }
36. 
37.     [TestMethod]
38.     public void FormatPhoneNumber_ValidDigits_ReturnsCorrectFormat()
39.     {
