64.         Assert.Contains("10 digits", ex.Message);
65.     }
66. 
67.     // --- BuildGreeting ---
68. 
69.     [TestMethod]
70.     public void BuildGreeting_WithDefaultTitle_StartsWithDearMr()
71.     {
72.         var result = _formatter.BuildGreeting("Smith");
73. 
