83.     }
84. 
85.     [TestMethod]
86.     public void BuildGreeting_WithCustomTitle_ContainsTitle()
87.     {
88.         var result = _formatter.BuildGreeting("Johnson", "Dr.");
89. 
90.         Assert.StartsWith("Dear Dr.", result);
91.         Assert.Contains("Johnson", result);
92.     }
93. 
94.     [TestMethod]
95.     public void BuildGreeting_WithName_ContainsName()
96.     {
97.         var result = _formatter.BuildGreeting("Smith");
98. 
99.         Assert.Contains("Smith", result);
100.     }
101. 
102.     [TestMethod]
103.     [DataRow(null)]
104.     [DataRow("")]
105.     [DataRow("   ")]
106.     public void BuildGreeting_InvalidName_ThrowsArgumentException(string? name)
107.     {
108.         Assert.Throws<ArgumentException>(
109.             () => _formatter.BuildGreeting(name!));
110.     }
111. 
112.     // --- GenerateSlug ---
113. 
114.     [TestMethod]
115.     public void GenerateSlug_SimpleTitle_ReturnsLowercaseWithHyphens()
116.     {
117.         var result = _formatter.GenerateSlug("Hello World");
118. 
119.         Assert.AreEqual("hello-world", result);
120.     }
121. 
122.     [TestMethod]
123.     public void GenerateSlug_TitleWithSpecialChars_MatchesSlugPattern()
124.     {
