169.     }
170. 
171.     [TestMethod]
172.     public void FormatCurrency_WithCustomSymbol_StartsWithSymbol()
173.     {
174.         var result = _formatter.FormatCurrency(19.99m, "€");
175. 
176.         Assert.StartsWith("€", result);
177.     }
178. 
