180.     public void FormatCurrency_WholeNumber_EndsWithTwoDecimalPlaces()
181.     {
182.         var result = _formatter.FormatCurrency(100m);
183. 
184.         Assert.EndsWith(".00", result);
185.     }
186. 
187.     [TestMethod]
188.     public void FormatCurrency_WithCents_MatchesDecimalPattern()
189.     {
190.         var result = _formatter.FormatCurrency(42.5m);
191. 
192.         Assert.MatchesRegex(@"^\$\d+\.\d{2}$", result);
193.     }
